+            result.Errors["Email"] = "Account has outstanding balance";
+        }
+
+        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
+        if (insuranceProvider == "None")
+        {
+            var doctor = Doctors.FirstOrDefault(d =>
+                string.Equals(d.Name, doctorName, StringComparison.OrdinalIgnoreCase));
+
+            if (doctor is not null && !doctor.AcceptsSelfPay)
+            {
+                result.Errors["Doctor"] = "Selected doctor does not accept self-pay patients";
+            }
+        }
+
+        // Reject "10:00 AM" as taken (simulates race condition)
+        if (timeSlot == "10:00 AM")
+        {
+            result.Errors["TimeSlot"] = "This slot is no longer available";
+        }
+
+        return Task.FromResult(result);
+    }
+}
